import Foundation

/// Decides whether a pasteboard change should go into the history.
public enum ClipboardFilter {
    /// Pasteboard types that password managers and apps use to mark a copy as secret or temporary.
    public static let secretTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    /// Longer text is ignored so one huge copy cannot bloat the history file.
    public static let maxTextLength = 1_000_000

    public static func shouldRecord(types: [String], text: String?) -> Bool {
        if !secretTypes.isDisjoint(with: types) { return false }
        guard let text else { return true }
        if text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return false }
        return text.count <= maxTextLength
    }
}
